#!/usr/bin/env python3
# load_cell_reader.py
# Reads weight from a load cell via MCP3002 ADC on Raspberry Pi 4 Model B
# Functional style, object-oriented implementation

import spidev
import time
import signal
import sys

# Configuration
SPI_BUS = 0
SPI_DEVICE = 0
REFERENCE_VOLTAGE = 5.0
MAX_RAW_VALUE = 1023.0
ADC_RESOLUTION = 10
SLEEP_INTERVAL = 0.5  # seconds

# Global variable to track SPI device
spi = None

def send_spi_command(spi, data):
    """Sends SPI command to the MCP3002 ADC."""
    try:
        return spi.xfer2(data)
    except (OSError, IOError) as e:
        print(f"SPI communication error: {e}")
        return None

def extract_10bit(response):
    """Extracts 10-bit ADC value from the SPI response."""
    if response is None:
        return None
    return ((response[1] & 0x03) << 8) | response[2]

def convert_to_weight(raw_data):
    """Converts raw ADC data to weight in kilograms."""
    if raw_data is None:
        return None
    return float(raw_data) * (REFERENCE_VOLTAGE / MAX_RAW_VALUE)

def read_raw_data(spi):
    """Reads raw data from the MCP3002 ADC channel 0."""
    command = [0x01, 0x80, 0x00]
    response = send_spi_command(spi, command)
    return extract_10bit(response)

def main():
    """Main function to read and display weight data."""
    global spi
    try:
        spi = spidev.SpiDev()
        spi.open(SPI_BUS, SPI_DEVICE)
        spi.max_speed_hz = 50000
        spi.mode = 0b00
        spi.bits_per_word = 8

        while True:
            raw_data = read_raw_data(spi)
            weight = convert_to_weight(raw_data)
            if weight is not None:
                print(f"Weight: {weight:.2f} kg")
            time.sleep(SLEEP_INTERVAL)

    except (OSError, IOError) as e:
        print(f"Error initializing SPI: {e}")
    except KeyboardInterrupt:
        print("Program terminated by user.")
    finally:
        if spi:
            try:
                spi.close()
                print("SPI connection closed.")
            except Exception as e:
                print(f"Error closing SPI: {e}")
        sys.exit(0)

if __name__ == "__main__":
    main()

