#!/usr/bin/env python3

import time
import logging
import sys
from picamera2 import Picamera2
from pyzbar.pyzbar import decode
from PIL import Image

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

# Constants
CAMERA_RESOLUTION = (640, 480)
DECODE_TIMEOUT = 5  # seconds

def initialize_camera():
    """Initializes the Raspberry Pi camera."""
    try:
        camera = Picamera2()
        camera.configure({"size": CAMERA_RESOLUTION})
        camera.start()
        return camera
    except Exception as e:
        logger.error(f"Camera initialization failed: {e}")
        return None

def capture_image(camera):
    """Captures an image from the camera and returns it as a PIL Image object."""
    try:
        array = camera.capture_array()
        image = Image.fromarray(array)
        return image
    except Exception as e:
        logger.error(f"Image capture failed: {e}")
        return None

def decode_qr_code(image):
    """Decodes QR codes in an image."""
    try:
        decoded_objects = decode(image)
        return decoded_objects
    except Exception as e:
        logger.error(f"QR code decoding failed: {e}")
        return None

def process_qr_code(decoded_objects):
    """Processes decoded QR codes."""
    if decoded_objects:
        for obj in decoded_objects:
            data = obj.data.decode("utf-8")
            logger.info(f"QR Code detected: {data}")
            # Add more processing logic here as needed
    else:
        logger.info("No QR code detected.")

def main():
    """Main function to capture image, decode QR code, and process the data."""
    logger.info("Starting QR code scanner...")

    camera = initialize_camera()
    if not camera:
        logger.error("Failed to initialize camera. Exiting.")
        sys.exit(1)

    try:
        image = capture_image(camera)
        if image:
            decoded_objects = decode_qr_code(image)
            process_qr_code(decoded_objects)
        else:
            logger.warning("No image captured. Exiting.")
    except Exception as e:
        logger.exception(f"An unexpected error occurred: {e}")
    finally:
        if camera:
            camera.stop()
            camera.close()
        logger.info("QR code scanner stopped.")

if __name__ == "__main__":
    main()

