#!/usr/bin/env python

from picamera2 import Picamera2
import time
import boto3 as b3
from typing import Tuple, Dict, Any
import os

# Constants
DEFAULT_COLLECTION = 'home'
DEFAULT_THRESHOLD = 85
IMAGE_FILENAME = 'image.jpg'
CAMERA_WARM_UP_TIME = 2

def create_client() -> b3.client:
    """Creates and returns a Rekognition client."""
    return b3.client('rekognition')

def capture_image(picam2: Picamera2) -> None:
    """Captures an image from the camera and saves it to a file."""
    try:
        picam2.capture_file(IMAGE_FILENAME)
    except Exception as e:
        raise RuntimeError(f"Error capturing image: {e}")

def detect_faces(client: b3.client, image_file: str) -> Dict[str, Any]:
    """Detects faces in an image file."""
    try:
        with open(image_file, 'rb') as image:
            response = client.detect_faces(Image={'Bytes': image.read()})
        return response
    except Exception as e:
        raise RuntimeError(f"Error detecting faces: {e}")

def search_faces(client: b3.client, collection: str, image_file: str) -> Dict[str, Any]:
    """Searches for faces in a Rekognition collection."""
    try:
        with open(image_file, 'rb') as image:
            response = client.search_faces_by_image(CollectionId=collection, Image={'Bytes': image.read()}, MaxFaces=1, FaceMatchThreshold=85)
        return response
    except Exception as e:
        raise RuntimeError(f"Error searching faces: {e}")


def initialize_camera() -> Picamera2:
    """Initializes the camera."""
    picam2 = Picamera2()
    picam2.configure(picam2.create_still_configuration())
    return picam2

def process_image(collection: str) -> None:
    """Captures an image, detects faces, and searches a Rekognition collection."""
    client = create_client()
    picam2 = initialize_camera()

    try:
        picam2.start()
        time.sleep(CAMERA_WARM_UP_TIME)
        capture_image(picam2)

        faces_response = detect_faces(client, IMAGE_FILENAME)
        if faces_response['FaceDetails']:
            print(f"Found {len(faces_response['FaceDetails'])} faces")
            faces_match_response = search_faces(client, collection, IMAGE_FILENAME)

            if faces_match_response['FaceMatches']:
                match = faces_match_response['FaceMatches'][0]
                print(f"Found a match with {match['Similarity']:.2f} similarity")
                # Example of accessing external image data (replace with your logic)
                external_image_id = match['Face']['ExternalImageId']
                print(f"External Image ID: {external_image_id}")
            else:
                print("No face matches found.")
        else:
            print("No faces detected in the image.")


    except Exception as e:
        print(f"An error occurred: {e}")
    finally:
        picam2.close()


if __name__ == "__main__":
    process_image(DEFAULT_COLLECTION)

