# Simple CPU Temperature Display for Raspberry Pi 5 (Beginner Tutorial)
# This script reads the CPU temperature and prints it to the console.

import smbus2
import time

# Define the I2C address of the OLED display (SSD1306)
OLED_ADDRESS = 0x3C

# Initialize I2C bus (bus 1 is the default on Raspberry Pi)
try:
    bus = smbus2.SMBus(1)
except Exception as e:
    print(f"Error initializing I2C bus: {e}")
    exit()

# Function to read CPU temperature
def get_cpu_temperature():
    try:
        with open("/sys/class/thermal/thermal_zone0/temp", "r") as f:
            temp_millidegrees = int(f.read())
            temp_celsius = temp_millidegrees / 1000.0
            return temp_celsius
    except FileNotFoundError:
        print("Error: Could not find temperature file.")
        return None
    except PermissionError:
        print("Error: Permission denied reading temperature.")
        return None
    except Exception as e:
        print(f"Error reading temperature: {e}")
        return None

# Main loop
try:
    while True:
        temperature = get_cpu_temperature()
        if temperature is not None:
            print(f"CPU Temperature: {temperature:.2f} °C")
        time.sleep(2)  # Wait 2 seconds
except KeyboardInterrupt:
    print("Exiting program.")
except Exception as e:
    print(f"An unexpected error occurred: {e}")
finally:
    try:
        bus.close() # Release the I2C bus
    except:
        pass
    print("Program finished.")

