import serial
import time

# Serial port configuration for the RS485 sensor
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 115200
TIMEOUT = 1

def read_temperature_data():
    """Reads temperature data from the RS485 sensor."""
    try:
        with serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT) as ser:
            while True:
                try:
                    line = ser.readline().decode('ascii', errors='replace').strip()
                    if line:
                        try:
                            temperature = float(line.split()[0])  # Extract temperature value
                            print(f'Temperature: {temperature:.1f} C')
                        except ValueError:
                            print("Error: Could not parse temperature from sensor data.")
                except serial.SerialException as e:
                    print(f"Serial communication error: {e}")
                time.sleep(0.5)
    except serial.SerialException as e:
        print(f"Failed to open serial port: {e}")
    except KeyboardInterrupt:
        print("Program terminated by user.")

if __name__ == "__main__":
    read_temperature_data()

