# Script to monitor relative altitude using a BMP280 sensor on Raspberry Pi
# Target: Raspberry Pi 3 Model B+
# Context: Assistive Technology

import time
import board
import busio
import adafruit_bmp280

# Constants
I2C_BUS = 1
BASELINE_READINGS = 10
BASELINE_READING_INTERVAL = 1  # seconds
ALTITUDE_INTERVAL = 1  # seconds
BMP280_ADDRESS = 0x76  # Default address, check your sensor

def initialize_i2c():
    """Initializes the I2C bus."""
    try:
        return busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Error initializing I2C: {e}")
        return None

def initialize_bmp280(i2c_bus):
    """Initializes the BMP280 sensor."""
    try:
        return adafruit_bmp280.Adafruit_BMP280_I2C(i2c_bus, address=BMP280_ADDRESS)
    except ValueError as e:
        print(f"Error initializing BMP280: {e}. Check I2C connection and address.")
        return None
    except Exception as e:
        print(f"An unexpected error occurred during BMP280 initialization: {e}")
        return None

def collect_baseline_pressure(sensor, num_readings, interval):
    """Collects baseline pressure readings and calculates the average."""
    print("Collecting baseline pressure. Please wait...")
    pressures = []
    for _ in range(num_readings):
        try:
            pressure = sensor.pressure
            pressures.append(pressure)
            time.sleep(interval)
        except OSError as e:
            print(f"Error reading pressure during baseline collection: {e}")
            continue  # Continue to next reading
        except Exception as e:
            print(f"An unexpected error occurred during baseline collection: {e}")
            continue

    if not pressures:
        print("No valid pressure readings collected for baseline.")
        return None

    # Exclude initial readings to avoid sensor instability
    valid_pressures = pressures[2:]  # Exclude first 2 readings
    if not valid_pressures:
        print("Not enough valid pressure readings after initial instability.")
        return None

    baseline = sum(valid_pressures) / len(valid_pressures)
    print("Baseline pressure established.")
    return baseline

def read_altitude(sensor, baseline_pressure):
    """Reads and prints the relative altitude."""
    try:
        altitude = sensor.altitude
        print(f'Relative altitude: {altitude:05.2f} meters')
    except OSError as e:
        print(f"Error reading altitude: {e}")
    except Exception as e:
        print(f"An unexpected error occurred during altitude reading: {e}")

def main():
    """Main function to run the altitude monitoring."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return  # Exit if I2C initialization failed

    bmp280_sensor = initialize_bmp280(i2c_bus)
    if bmp280_sensor is None:
        return  # Exit if BMP280 initialization failed

    baseline = collect_baseline_pressure(bmp280_sensor, BASELINE_READINGS, BASELINE_READING_INTERVAL)
    if baseline is None:
        return  # Exit if baseline pressure collection failed

    print("Monitoring altitude. Press Ctrl+C to exit.")
    try:
        while True:
            read_altitude(bmp280_sensor, baseline)
            time.sleep(ALTITUDE_INTERVAL)
    except KeyboardInterrupt:
        print("Exiting program.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        print("Program finished.")

if __name__ == "__main__":
    main()

