import RPi.GPIO as GPIO
import time
import requests
import adafruit_dht

# Define sensor and server parameters
DHT_PIN = 4  # GPIO pin connected to DHT11 data pin
SERVER_URL = 'http://127.0.0.1:5000/data'  # URL of the Flask server

# Initialize DHT11 sensor
dht_device = adafruit_dht.DHT11(DHT_PIN)

def read_sensor_data():
    """Reads temperature and humidity from the DHT11 sensor."""
    try:
        temperature = dht_device.temperature
        humidity = dht_device.humidity
        return temperature, humidity
    except RuntimeError as error:
        # Errors happen fairly often, DHT's are hard to read, just keep going
        print(error.args[0])
        return None, None
    except Exception as error:
        dht_device.exit()
        raise error

def send_data_to_server(temperature, humidity):
    """Sends temperature and humidity data to the Flask server."""
    try:
        payload = {'temperature': temperature, 'humidity': humidity}
        response = requests.post(SERVER_URL, json=payload)
        print(f"Data sent. Server response: {response.status_code}")
    except requests.exceptions.RequestException as e:
        print(f"Error sending data: {e}")

def main():
    """Main function to read sensor data and send it to the server."""
    try:
        while True:
            temperature, humidity = read_sensor_data()

            if temperature is not None and humidity is not None:
                print(f"Temperature: {temperature:.1f}°C, Humidity: {humidity:.1f}%")
                send_data_to_server(temperature, humidity)

            time.sleep(5)  # Wait 5 seconds before the next reading

    except KeyboardInterrupt:
        print("Program stopped by user.")
    except Exception as e:
        print(f"An error occurred: {e}")
    finally:
        GPIO.cleanup()  # Clean up GPIO on exit

if __name__ == "__main__":
    main()

