# Monitors three digital input sensors on a Raspberry Pi using gpiozero.
# Designed for a robotics project on Raspberry Pi 4 Model B.

import time
import signal
import sys
from gpiozero import DigitalInputDevice

# Define GPIO pins for the sensors (BCM numbering)
SENSOR_PINS = [17, 27, 22]

# Define a function to handle program exit gracefully
def signal_handler(sig, frame):
    """Handles Ctrl+C and SIGTERM signals for graceful exit."""
    print("\nExiting program...")
    # Release GPIO resources
    for pin in SENSOR_PINS:
        try:
            sensor = DigitalInputDevice(pin, pull_up=True)
            sensor.close()
        except Exception as e:
            print(f"Error closing sensor on pin {pin}: {e}")
    sys.exit(0)

# Register the signal handler for Ctrl+C and SIGTERM
signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

def main():
    """Main function to monitor the sensors."""
    print("Starting sensor monitoring...")

    # Initialize sensor objects
    sensors = []
    for pin in SENSOR_PINS:
        try:
            sensor = DigitalInputDevice(pin, pull_up=True)
            sensors.append(sensor)
            print(f"Sensor on pin {pin} initialized.")
        except Exception as e:
            print(f"Error initializing sensor on pin {pin}: {e}")
            # Attempt to continue with the other sensors

    # Define the response for each sensor
    sensor_responses = {
        0: "Response for sensor 1",
        1: "Response for sensor 2",
        2: "Response for sensor 3"
    }

    # Main loop to continuously monitor the sensors
    try:
        while True:
            for i, sensor in enumerate(sensors):
                try:
                    if sensor.is_active:  # Check if the sensor is active (HIGH)
                        print(sensor_responses[i])
                except Exception as e:
                    print(f"Error reading sensor on pin {SENSOR_PINS[i]}: {e}")
            time.sleep(1)  # Poll every 1 second

    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        # Ensure GPIO resources are released on exit
        print("Cleaning up GPIO resources...")
        for sensor in sensors:
            try:
                sensor.close()
            except Exception as e:
                print(f"Error closing sensor: {e}")
        print("Program finished.")

if __name__ == "__main__":
    main()

