import sys
import threading
import time
import RPi.GPIO as GPIO
import DOGProtocol as DOG  # Assuming this module exists

# Constants
DEFAULT_FILENAME = "data.log"
PROMPT = "JAYES@ROVER53:\t"
RECEIVE_TIMEOUT = 0.1  # Timeout for receive attempts

# Configuration
GPIO.setwarnings(False)
GPIO.setmode(GPIO.BCM)

# State Variables
server_running = False
file_descriptor = None
receive_thread = None
receive_callback = None


def cleanup_gpio(signal=None, frame=None):
    """Cleanup GPIO resources."""
    print("\nExiting, cleaning up GPIO...")
    GPIO.cleanup()


def initialize():
    """Initialize the server."""
    try:
        GPIO.setup(DOG.GPIO_PIN, DOG.GPIO_MODE)
    except Exception as e:
        print(f"Error initializing GPIO: {e}")
        sys.exit(1)


def receive_loop():
    """Continuously receive data and write to the log file."""
    global file_descriptor  # Access the outer scope's file_descriptor

    while server_running:
        try:
            data = DOG.receive()
            if data:  # Check if any data was received
                try:
                    file_descriptor.write(data + "\n")
                    file_descriptor.flush()  # Ensure data is written immediately
                except IOError as e:
                    print(f"Error writing to file: {e}")
                    stop_server()
                    break  # Exit the loop after stopping the server
        except Exception as e:
            print(f"Receive error: {e}")
            time.sleep(RECEIVE_TIMEOUT)  # Prevent excessive error printing


def start_server(filename):
    """Start the data logging server."""
    global server_running, file_descriptor, receive_thread

    if server_running:
        print("Server already running.")
        return

    try:
        file_descriptor = open(filename, "a+")
        file_descriptor.seek(0, 2)  # Go to the end of the file
    except IOError as e:
        print(f"Error opening file: {e}")
        return

    server_running = True
    receive_thread = threading.Thread(target=receive_loop, name='ReceiveThread', daemon=True)
    receive_thread.start()

    print(f"Server started. Logging to: {filename}")


def stop_server():
    """Stop the data logging server."""
    global server_running, file_descriptor, receive_thread

    if not server_running:
        print("Server not running.")
        return

    server_running = False

    # Wait for the receive thread to finish (optional, but good practice)
    if receive_thread:
        receive_thread.join(timeout=2)  # Give it 2 seconds to finish

    try:
        if file_descriptor:
            file_descriptor.close()
    except Exception as e:
        print(f"Error closing file: {e}")

    file_descriptor = None
    receive_thread = None
    print("Server stopped.")


def help_command(command=None):
    """Display help information."""
    if command:
        if command == "help":
            print("Shows help information.")
        elif command == "start":
            print("Starts the server.")
        # ... (similar help messages for other commands)
        elif command == "exit":
            print("Closes the server and exits.")
        else:
            print("No help found for command:", command)
    else:
        print("\nAvailable commands:")
        print("  help          Shows help information")
        print("  help <cmd>    Shows help for a specific command")
        print("  start         Starts the server")
        print("  display       Prints the logged data")
        print("  send <data>   Sends data using DOGProtocol")
        print("  write <data>  Writes data directly to the log file")
        print("  stop          Stops the server")
        print("  exit          Closes the server and exits\n")



def display_log(filename=DEFAULT_FILENAME):
    """Display the contents of the log file."""
    try:
        with open(filename, "r") as f:
            print(f.read())
    except IOError as e:
        print(f"Error opening log file: {e}")



def send_data(data):
    """Send data using DOGProtocol."""
    if not server_running:
        print("Server must be started first. Use the 'start' command.")
        return

    try:
        DOG.send(data)
    except Exception as e:
        print(f"Send error: {e}")


def write_to_log(data):
    """Write data directly to the log file."""
    global file_descriptor
    if not server_running:
        print("Server must be started first. Use the 'start' command.")
        return

    try:
        file_descriptor.write(data + "\n")
        file_descriptor.flush()
    except IOError as e:
        print(f"Error writing to log: {e}")



def run_server():
    """Main server loop."""
    while True:
        try:
            command = input(PROMPT).strip()
            args = command.split()
            if not args:
                continue

            if args[0] == "help":
                help_command(*args[1:])
            elif args[0] == "start":
                start_server(*args[1:])
            elif args[0] == "display":
                display_log(*args[1:])
            elif args[0] == "send":
                send_data(*args[1:])
            elif args[0] == "write":
                write_to_log(*args[1:])
            elif args[0] == "stop":
                stop_server()
            elif args[0] == "exit":
                stop_server()
                print("Exiting...")
                sys.exit(0)
            else:
                print("Unknown command. Try 'help'")

        except KeyboardInterrupt:
            print("\nKeyboard interrupt. Use 'exit' to quit.")
        except Exception as e:
            print(f"An unexpected error occurred: {e}")



if __name__ == "__main__":
    initialize()
    signal.signal(signal.SIGINT, cleanup_gpio)  # Register signal handler
    signal.signal(signal.SIGTERM, cleanup_gpio)
    print("Data Logging Server")
    run_server()

