import zmq
import time
import json
import RPi.GPIO as GPIO
import logging
from worker_K10CR1 import WK10CR1
from worker_DAC8532 import WDAC8532
from typing import Callable, Any, Dict, List, Tuple

class SubscriptionHandler:
    """Handles subscriptions and control actions for data streams."""

    def __init__(self, logger: logging.Logger, monitor_socket: zmq.Socket):
        """
        Initializes the SubscriptionHandler.

        Args:
            logger: Logger instance for logging.
            monitor_socket: ZMQ socket for sending monitoring messages.
        """
        self.logger = logger
        self.subscriptions: Dict[str, List[Callable[[Any], None]]] = {}
        self.subscription_info: Dict[str, Dict[str, Any]] = {}  # Store subscription details
        self.monitor_socket = monitor_socket

    def handle_command(self, command: dict, subscription_key: str) -> None:
        """
        Handles commands related to subscriptions, updates, and control.

        Args:
            command: A dictionary containing the command details.
                     Expected keys: 'action', 'stream_filter', 'callback', 'kwargs', 'id'
            subscription_key: The key identifying the subscription.
        """

        action = command.get('action')
        callback = command.get('callback', None)

        if not callable(callback):
            if action not in ['SUBSCRIBE', 'UNSUBSCRIBE', 'REMOVE_ALL_CBS'):
                self.logger.warning(f"Subscription '{subscription_key}': Command missing 'callback' or 'action' is invalid.  Command ignored: {command}")
                return

        if action == 'SUBSCRIBE':
            stream_filter = command['stream_filter']
            kwargs = command['kwargs']
            subscription_list = self.subscriptions.setdefault(stream_filter, [])
            subscription_info = self.subscription_info.setdefault(stream_filter, {})

            subscription_list.append(callback)
            subscription_info[subscription_key] = {
                'kwargs': kwargs,
                'state': {},
                'control': {'alert': True, 'pause': False},
                'class_instance': self._create_worker_instance(kwargs)  # Create worker instance
            }

            self.logger.info(f"Subscription '{subscription_key}': Now listening for stream '{stream_filter}'.")
            self._update_monitor(subscription_key, 'SUB', 1)

        elif action == 'UPDATE_KW':
            # ... (similar to previous implementation)
            pass

        elif action == 'UNSUBSCRIBE':
            # ... (similar to previous implementation)
            pass

        elif action == 'REMOVE_ALL_CBS':
            # ... (similar to previous implementation)
            pass

        elif action == 'RESET':
            # ... (similar to previous implementation)
            pass

        elif action == 'RESET_ALL':
            # ... (similar to previous implementation)
            pass

        elif action == 'MUTE':
            # ... (similar to previous implementation)
            pass

        elif action == 'UNMUTE':
            # ... (similar to previous implementation)
            pass

        elif action == 'MUTE_ALL':
            # ... (similar to previous implementation)
            pass

        elif action == 'UNMUTE_ALL':
            # ... (similar to previous implementation)
            pass

        elif action == 'PAUSE_ALL':
            # ... (similar to previous implementation)
            pass

        elif action == 'RESTART_ALL':
            # ... (similar to previous implementation)
            pass

        elif action == 'PAUSE':
            # ... (similar to previous implementation)
            pass

        elif action == 'RESTART':
            # ... (similar to previous implementation)
            pass


    def _create_worker_instance(self, kwargs: dict) -> object:
        """Creates and initializes a worker instance based on kwargs."""
        class_name = kwargs.get('class_name')
        if not class_name:
            self.logger.error("Worker class name not specified in kwargs.")
            return None

        try:
            module_name, class_name = class_name.rsplit('.', 1)
            module = __import__(module_name, fromlist=[class_name])
            worker_class: object = getattr(module, class_name)  # type: ignore
            if not callable(getattr(worker_class, 'update', None)):
                raise TypeError(f"{class_name} doesn't implement update()")
            if not callable(getattr(worker_class, 'reset': None)):
                raise TypeError(f"{class_name} doesn't implement reset()")

            worker = worker_class(**kwargs)
            return worker
        except (ImportError, AttributeError, TypeError) as e:
            self.logger.error(f"Error creating worker instance: {e}")
            return None


    def update_subscription(self, subscription_key: str, data: dict) -> None:
        """Updates subscribed callbacks with the given data."""
        for callbacks in self.subscriptions.values():
            for callback in callbacks:
                callback(data)


    def _update_monitor(self, subscription_key: str, command: str, param: int) -> None:
        """Sends update messages to the monitoring socket."""
        try:
            self.monitor_socket.send_string(subscription_key, zmq.SNDMORE)
            self.monitor_socket.send_string(command)
            self.monitor_socket.send_string(str(param))
        except zmq.ZMQError as e:
            self.logger.error(f"Error updating monitor: {e}")


    def cleanup(self) -> None:
        """Performs cleanup actions for all subscriptions."""
        for stream_filter, info_list in self.subscription_info.items():
            for subscription_key, info in info_list.items():
                if info['class_instance']:
                    try:
                        info['class_instance'].close()
                        self.logger.info(f"Subscription '{subscription_key}': Cleanup complete.")
                    except Exception as e:
                        self.logger.error(f"Error cleaning up worker: {e}")
