import socket
import json
import time
import signal
import sys
import logging
import threading
import random

# Configure logging for the wildlife tracking remote control server
logging.basicConfig(level=logging.INFO, format="%(asctime)s %(message)s")

# TCP listening parameters for the remote control socket
LISTEN_HOST = "127.0.0.1"
LISTEN_PORT = 9099
SOCKET_TIMEOUT = 2.0

# Global tracking state reported back to the remote controller
tracking_state = "stopped"


def read_gps_position(gps_module):
    """Read a simulated GPS coordinate pair from the GPS module."""
    # In a real deployment this reads NMEA sentences from pyserial or smbus2
    try:
        if gps_module is None:
            return {"lat": round(random.uniform(51.0, 52.0), 6),
                    "lon": round(random.uniform(-1.0, 0.0), 6)}
        # A real GPS would parse GPRMC sentences here
        return {"lat": 51.5074, "lon": -0.1278}
    except Exception as read_error:
        logging.error("Failed to read GPS: %s", read_error)
        return None


def handle_command(gps_module, command_text):
    """Process a remote control command and return a JSON response."""
    global tracking_state
    # Decode and dispatch the incoming remote control command
    command = command_text.strip().lower()
    if command == "start":
        tracking_state = "running"
        response_body = {"state": tracking_state}
    elif command == "stop":
        tracking_state = "stopped"
        response_body = {"state": tracking_state}
    elif command == "report":
        position = read_gps_position(gps_module)
        if position is None:
            return json.dumps({"error": "no gps fix"})
        response_body = {"state": tracking_state, "position": position}
    else:
        response_body = {"error": "unknown command"}
    return json.dumps(response_body)


def main():
    """Run the remote control server for the wildlife tracking node."""
    gps_module = None
    server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    server_socket.settimeout(SOCKET_TIMEOUT)
    try:
        # Bind the socket and listen for incoming connections
        server_socket.bind((LISTEN_HOST, LISTEN_PORT))
        server_socket.listen(1)
        logging.info("Listening on %s:%d", LISTEN_HOST, LISTEN_PORT)
        while True:
            try:
                client_connection, client_address = server_socket.accept()
                client_connection.settimeout(SOCKET_TIMEOUT)
                command_text = client_connection.recv(1024).decode("utf-8")
                response_text = handle_command(gps_module, command_text)
                client_connection.sendall(response_text.encode("utf-8"))
                client_connection.close()
            except socket.timeout:
                logging.info("Socket timeout waiting for a connection")
            except Exception as server_error:
                logging.error("Server error: %s", server_error)
    except OSError as bind_error:
        logging.error("Could not bind socket: %s", bind_error)
    finally:
        # Close the listening socket on shutdown
        server_socket.close()


if __name__ == "__main__":
    main()

