#!/usr/bin/env python3
import time
import automationhat
import logging
import sys

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

# Constants
DOOR_CLOSED = 1
DOOR_OPEN = 0
RELAY_ON_DURATION = 0.5  # seconds

class GarageDoor:
    """
    A class to represent and control a garage door using an Automation HAT.

    Attributes:
        state_pin (int): The input pin number on the Automation HAT connected to the door state sensor.
        name (str, optional): The name of the garage door. Defaults to "My Door".
    """

    def __init__(self, state_pin, name="My Door"):
        if not isinstance(state_pin, int):
            raise TypeError("state_pin must be an integer")

        if not 1 <= state_pin <= 3:
            raise ValueError("state_pin must be between 1 and 3")

        self.state_pin = state_pin
        self.name = name
        self._validate_automationhat()  # Check if Automation HAT is properly initialized

    def _validate_automationhat(self):
        """
        Validates that the automationhat library is properly initialized and the HAT is connected.
        Raises an exception if the validation fails.
        """
        try:
            if automationhat.is_pro:
                logger.warning("Running in PRO mode. Ensure hardware is correctly wired.")
            else:
                logger.info("Running in STEM mode.")
        except Exception as e:
            logger.error(f"Error initializing automationhat: {e}")
            raise

    def trigger(self):
        """
        Triggers the garage door relay to simulate pressing the remote control.
        """
        try:
            automationhat.relay.one.on()
            time.sleep(RELAY_ON_DURATION)
            automationhat.relay.one.off()
            logger.info(f"{self.name}: Relay triggered to change door state.")
        except Exception as e:
            logger.error(f"{self.name}: Error triggering relay: {e}")
            raise

    @property
    def state(self):
        """
        Gets the current state of the garage door (OPEN or CLOSED) based on the state pin input.
        Returns:
            int: DOOR_OPEN (0) if the state pin is LOW, DOOR_CLOSED (1) if the state pin is HIGH.
        """
        try:
            # Read the input value from the specified pin.  Returns 1 for HIGH, 0 for LOW.
            input_value = automationhat.input[self.state_pin - 1].read()

            if input_value is None:
                raise ValueError(f"Unexpected None value from automationhat.input[{self.state_pin - 1}].read()")

            if input_value == 1:
                return DOOR_CLOSED  # Door is closed when the pin reads HIGH
            elif input_value == 0:
                return DOOR_OPEN   # Door is open when the pin reads LOW
            else:
                raise ValueError(f"Unexpected input value: {input_value} from automationhat.input[{self.state_pin - 1}].read()")

        except Exception as e:
            logger.error(f"{self.name}: Error reading door state: {e}")
            raise

    @state.setter
    def state(self, value):
        """
        Raises an AttributeError to prevent direct setting of the door state.
        """
        raise AttributeError("Cannot set the state attribute directly.  Read only.")

    @property
    def is_open(self):
        """
        Returns True if the door is currently open, False if it is closed.
        """
        return self.state == DOOR_OPEN

    @property
    def is_closed(self):
        """
        Returns True if the door is currently closed, False if it is open.
        """
        return self.state == DOOR_CLOSED


def main():
    """
    Main function to demonstrate the usage of the GarageDoor class.
    """
    try:
        garage_door = GarageDoor(state_pin=1, name="Home Garage Door")
        logger.info("Garage door object created.")

        if garage_door.is_closed:
            logger.info("Garage door is currently closed.")
            try:
                garage_door.trigger()
                time.sleep(5)  # Wait for the door to open
                if garage_door.is_open:
                    logger.info("Garage door is now open.")
                else:
                    logger.error("Garage door failed to open.")
            except Exception as e:
                logger.error(f"Failed to open garage door: {e}")

        elif garage_door.is_open:
            logger.info("Garage door is currently open.")
            try:
                garage_door.trigger()
                time.sleep(5)  # Wait for the door to close
                if garage_door.is_closed:
                    logger.info("Garage door is now closed.")
                else:
                    logger.error("Garage door failed to close.")
            except Exception as e:
                logger.error(f"Failed to close garage door: {e}")


    except (ValueError, TypeError, automationhat.AHError) as e:  # Catch initialization errors
        logger.error(f"Initialization error: {e}")
        sys.exit(1) # Indicate an error
    except Exception as e:
        logger.exception(f"An unexpected error occurred: {e}")
        sys.exit(1)
    finally:
        # Ensure relay is off on exit to prevent unexpected behavior
        try:
            automationhat.relay.one.off()
        except Exception as e:
            logger.error(f"Error turning off relay in finally block: {e}")


if __name__ == "__main__":
    main()

