            logger.error(f"{self.name}: Error triggering relay: {e}")
            raise

    @property
    def state(self):
        """
        Gets the current state of the garage door (OPEN or CLOSED) based on the state pin input.
        Returns:
            int: DOOR_OPEN (0) if the state pin is LOW, DOOR_CLOSED (1) if the state pin is HIGH.
        """
        try:
            # Read the input value from the specified pin.  Returns 1 for HIGH, 0 for LOW.
            input_value = automationhat.input[self.state_pin - 1].read()

            if input_value is None:
                raise ValueError(f"Unexpected None value from automationhat.input[{self.state_pin - 1}].read()")

            if input_value == 1:
                return DOOR_CLOSED  # Door is closed when the pin reads HIGH
            elif input_value == 0:
                return DOOR_OPEN   # Door is open when the pin reads LOW
            else:
                raise ValueError(f"Unexpected input value: {input_value} from automationhat.input[{self.state_pin - 1}].read()")

        except Exception as e:
            logger.error(f"{self.name}: Error reading door state: {e}")
            raise

    @state.setter
    def state(self, value):
        """
        Raises an AttributeError to prevent direct setting of the door state.
        """
        raise AttributeError("Cannot set the state attribute directly.  Read only.")

    @property
    def is_open(self):
        """
        Returns True if the door is currently open, False if it is closed.
        """
        return self.state == DOOR_OPEN

    @property
    def is_closed(self):
        """
        Returns True if the door is currently closed, False if it is open.
        """
        return self.state == DOOR_CLOSED


def main():
