        logger.info("Garage door object created.")

        if garage_door.is_closed:
            logger.info("Garage door is currently closed.")
            try:
                garage_door.trigger()
                time.sleep(5)  # Wait for the door to open
                if garage_door.is_open:
                    logger.info("Garage door is now open.")
                else:
                    logger.error("Garage door failed to open.")
            except Exception as e:
                logger.error(f"Failed to open garage door: {e}")

        elif garage_door.is_open:
            logger.info("Garage door is currently open.")
            try:
                garage_door.trigger()
                time.sleep(5)  # Wait for the door to close
                if garage_door.is_closed:
                    logger.info("Garage door is now closed.")
                else:
                    logger.error("Garage door failed to close.")
            except Exception as e:
                logger.error(f"Failed to close garage door: {e}")


    except (ValueError, TypeError, automationhat.AHError) as e:  # Catch initialization errors
        logger.error(f"Initialization error: {e}")
        sys.exit(1) # Indicate an error
    except Exception as e:
        logger.exception(f"An unexpected error occurred: {e}")
        sys.exit(1)
    finally:
        # Ensure relay is off on exit to prevent unexpected behavior
        try:
            automationhat.relay.one.off()
        except Exception as e:
            logger.error(f"Error turning off relay in finally block: {e}")


