# hydroponics control assistant for Raspberry Pi using gpiozero
# Parses plain English phrases into intents and drives actuators
from gpiozero import OutputDevice
import logging

# Configure logging for the hydroponics control system
logging.basicConfig(level=logging.INFO, format="%(asctime)s %(message)s")

# Define BCM GPIO pins for the hydroponics control actuators
NUTRIENT_PUMP_PIN = 20
GROW_LIGHT_PIN = 21

# Initialize gpiozero OutputDevice objects for the actuators
# These represent the nutrient pump and grow light relays
try:
    nutrient_pump = OutputDevice(NUTRIENT_PUMP_PIN)
    grow_light = OutputDevice(GROW_LIGHT_PIN)
except Exception as e:
    logging.error(f"Actuator initialization failed: {e}")
    nutrient_pump = None
    grow_light = None


def parse_phrase(phrase):
    """Parses a plain English phrase into a hydroponics control intent."""
    # Convert the phrase to lowercase for case-insensitive matching
    phrase = phrase.lower()
    if "pump on" in phrase:
        return "pump_on"
    elif "pump off" in phrase:
        return "pump_off"
    elif "light toggle" in phrase:
        return "light_toggle"
    else:
        return "unknown"


def apply_intent(intent):
    """Applies the parsed intent to the hydroponics control actuators."""
    # Execute the corresponding action based on the parsed intent
    if intent == "pump_on" and nutrient_pump:
        nutrient_pump.on()
        logging.info("Nutrient pump turned on")
    elif intent == "pump_off" and nutrient_pump:
        nutrient_pump.off()
        logging.info("Nutrient pump turned off")
    elif intent == "light_toggle" and grow_light:
        grow_light.toggle()
        logging.info("Grow light toggled")
    elif intent == "unknown":
        logging.warning("Unknown command received")


def main():
    """Main function to process phrases and control the hydroponics system."""
    # List of test phrases for the hydroponics control assistant
    phrases = [
        "turn the pump on",
        "switch the light",
        "turn pump off",
        "unknown command",
    ]
    try:
        for phrase in phrases:
            intent = parse_phrase(phrase)
            logging.info(f"Parsed intent: {intent} from phrase: {phrase}")
            apply_intent(intent)
    except KeyboardInterrupt:
        logging.info("Exiting hydroponics control script")
    except Exception as e:
        logging.error(f"An error occurred: {e}")
    finally:
        # Ensure all actuators are safely turned off on exit
        if nutrient_pump:
            nutrient_pump.close()
        if grow_light:
            grow_light.close()


if __name__ == "__main__":
    main()

