import smbus2
import time

# I2C device helper class for Raspberry Pi using smbus2
class I2CDevice:
    """A helper class to interact with I2C devices on a Raspberry Pi."""

    def __init__(self, address, bus_number=1):
        """Initialize the I2C device.

        Args:
            address (int): The I2C address of the device.
            bus_number (int): The I2C bus number (default is 1).
        """
        self.address = address
        try:
            self.bus = smbus2.SMBus(bus_number)
        except Exception as e:
            raise RuntimeError(f"Failed to open I2C bus: {e}")

    def check_device(self):
        """Check if the device acknowledges its address."""
        try:
            self.bus.read_byte(self.address)
            return True
        except Exception:
            return False

    def write_byte(self, register, value):
        """Write a byte to a register on the I2C device.

        Args:
            register (int): The register address to write to.
            value (int): The byte value to write.
        """
        try:
            self.bus.write_byte_data(self.address, register, value)
        except OSError as e:
            raise RuntimeError(f"Failed to write byte: {e}")

    def read_byte(self, register):
        """Read a byte from a register on the I2C device.

        Args:
            register (int): The register address to read from.

        Returns:
            int: The byte value read from the register.
        """
        try:
            return self.bus.read_byte_data(self.address, register)
        except OSError as e:
            raise RuntimeError(f"Failed to read byte: {e}")

    def close(self):
        """Close the I2C bus connection."""
        try:
            self.bus.close()
        except Exception as e:
            print(f"Error closing I2C bus: {e}")

    def __enter__(self):
        """Context management entry."""
        if not self.check_device():
            raise RuntimeError(f"I2C device not found at address: 0x{self.address:02X}")
        return self

    def __exit__(self, exc_type, exc_value, traceback):
        """Context management exit, closing the bus."""
        self.close()

