#!/usr/bin/python3
# -*- coding: utf-8 -*-

"""
DS1338 Real-Time Clock (RTC) Driver for Raspberry Pi

This module provides a driver for the DS1338 RTC chip, utilizing the SMBus.
It offers functionalities to read and write date and time information to the RTC.
"""

import smbus2 as smbus
from datetime import datetime
import logging
import sys

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

# Constants for I2C bus and device address
DEFAULT_I2C_BUS = 1
DEFAULT_DEVICE_ADDRESS = 0x68

# Register addresses for the DS1338
REGISTERS = {
    "seconds": 0x00,
    "minutes": 0x01,
    "hours": 0x02,
    "day": 0x03,
    "date": 0x04,
    "month": 0x05,
    "year": 0x06,
    "control": 0x07
}


def bcd_to_int(bcd_value):
    """Converts a BCD value to an integer."""
    try:
        return (bcd_value >> 4) * 10 + (bcd_value & 0x0F)
    except TypeError:
        logger.error("Invalid BCD value provided: %s", bcd_value)
        return None


def int_to_bcd(int_value):
    """Converts an integer to BCD format."""
    if not 0 <= int_value <= 99:
        raise ValueError("Integer value must be between 0 and 99 for BCD conversion.")
    return (int_value // 10 << 4) | (int_value % 10)


class DS1338:
    """Driver for the DS1338 Real-Time Clock (RTC) chip."""

    def __init__(self, i2c_bus=DEFAULT_I2C_BUS, device_address=DEFAULT_DEVICE_ADDRESS):
        """Initializes the DS1338 driver."""
        self.i2c_bus = i2c_bus
        self.device_address = device_address
        try:
            self.bus = smbus.SMBus(self.i2c_bus)
            logger.info("DS1338 initialized successfully.")
        except Exception as e:
            logger.error("Failed to initialize DS1338: %s", e)
            sys.exit(1)  # Exit with error code


    def _write_register(self, register, value):
        """Writes a byte to a specific register."""
        try:
            self.bus.write_byte_data(self.device_address, register, value)
        except IOError as e:
            logger.error("IOError writing to register 0x%02X: %s", register, e)
            raise
        except Exception as e:
            logger.error("Unexpected error writing to register 0x%02X: %s", register, e)
            raise

    def _read_register(self, register):
        """Reads a byte from a specific register."""
        try:
            return self.bus.read_byte_data(self.device_address, register)
        except IOError as e:
            logger.error("IOError reading from register 0x%02X: %s", register, e)
            raise
        except Exception as e:
            logger.error("Unexpected error reading from register 0x%02X: %s", register, e)
            raise


    def read_all(self):
        """Reads all RTC registers and returns them as a dictionary."""
        rtc_data = {}
        for register_name, register_address in REGISTERS.items():
            try:
                rtc_data[register_name] = self._read_register(register_address)
            except IOError:
                # Continue reading even if an error occurs, but log the issue
                logger.warning(f"Error reading register: {register_name}")
                rtc_data[register_name] = None  # Store None to indicate failure
        return rtc_data


    def read_datetime(self, century=21):
        """Reads the date and time and returns a datetime object."""
        try:
            rtc_data = self.read_all()
            if all(value is not None for value in rtc_data.values()):
                year = rtc_data["year"] + (century - 1) * 100
                return datetime(
                    year, bcd_to_int(rtc_data["month"]), bcd_to_int(rtc_data["date"]),
                    bcd_to_int(rtc_data["hours"] & 0x3F), bcd_to_int(rtc_data["minutes"]),
                    bcd_to_int(rtc_data["seconds"])
                )
            else:
                logger.warning("Incomplete data read. Returning None.")
                return None
        except Exception as e:
            logger.error("Error reading datetime: %s", e)
            return None


    def write_all(self, year, month, date, day, hours, minutes, seconds):
        """Writes all RTC registers."""

        if not all(0 <= val <= limit for val, limit in [(seconds, 59), (minutes, 59), (hours, 23),
                                                      (day, 7), (date, 31), (month, 12), (year, 99)]):
            raise ValueError("Date and time values are out of range.")


        try:
            self._write_register(REGISTERS["seconds"], int_to_bcd(seconds))
            self._write_register(REGISTERS["minutes"], int_to_bcd(minutes))
            self._write_register(REGISTERS["hours"], int_to_bcd(hours))  # Removed 24-hour mode enforcement
            self._write_register(REGISTERS["day"], int_to_bcd(day))
            self._write_register(REGISTERS["date"], int_to_bcd(date))
            self._write_register(REGISTERS["month"], int_to_bcd(month))
            self._write_register(REGISTERS["year"], int_to_bcd(year % 100)) # Ensure year is within 0-99
            logger.info("Date and time written successfully.")

        except Exception as e:
            logger.error("Error writing datetime: %s", e)


    def write_datetime(self, dt):
        """Writes the current time to the RTC from a datetime object."""
        if not isinstance(dt, datetime):
            raise TypeError("Input must be a datetime object.")

        try:
            self.write_all(
                dt.year % 100, dt.month, dt.day, dt.isoweekday(),
                dt.hour, dt.minute, dt.second
            )
        except Exception as e:
            logger.error("Error writing datetime: %s", e)


    def write_now(self):
        """Writes the current system time to the RTC."""
        try:
            now = datetime.now(timezone.utc).astimezone() # Get timezone-aware UTC time
            self.write_datetime(now)
            logger.info("RTC time synchronized with system time.")
        except Exception as e:
            logger.error("Error synchronizing time: %s", e)


    def close(self):
        """Closes the I2C bus connection."""
        try:
            self.bus.close()
            logger.info("I2C bus closed.")
        except Exception as e:
            logger.error("Error closing I2C bus: %s", e)


    def __enter__(self):
        """Context management entry."""
        return self


    def __exit__(self, exc_type, exc_val, exc_tb):
        """Context management exit, closes the bus."""
        self.close()

