# Reads radiation data from a UART sensor and triggers an alarm via GPIO on a Raspberry Pi
import serial
import time
from gpiozero import LED

# Serial port configuration for the radiation sensor
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1

# GPIO pin connected to the alarm indicator
ALARM_GPIO_PIN = 18

# Radiation threshold in microsieverts per hour
RADIATION_THRESHOLD = 50.0


def initialize_serial(port, baud, timeout):
    """Opens and returns a serial port connection."""
    try:
        return serial.Serial(port, baud, timeout=timeout)
    except serial.SerialException as error:
        print(f"Error opening serial port: {error}")
        exit(1)


def initialize_alarm(pin):
    """Initializes the alarm LED on the given GPIO pin."""
    return LED(pin)


def read_radiation_level(serial_connection):
    """Reads a line from the serial port and returns the radiation level as a float."""
    try:
        line = serial_connection.readline().decode('ascii', errors='replace').strip()
        if line:
            return float(line)
        return None
    except ValueError:
        print("Warning: Non-numeric data received from sensor.")
        return None


def update_alarm(alarm_device, radiation_level, threshold):
    """Activates or deactivates the alarm based on the radiation level."""
    if radiation_level is not None:
        if radiation_level > threshold:
            alarm_device.on()
        else:
            alarm_device.off()


def main():
    """Main function to read radiation data and control the alarm."""
    serial_connection = initialize_serial(SERIAL_PORT, BAUD_RATE, TIMEOUT)
    alarm_device = initialize_alarm(ALARM_GPIO_PIN)

    try:
        while True:
            radiation_level = read_radiation_level(serial_connection)
            if radiation_level is not None:
                print(f"Radiation level: {radiation_level:.2f} µSv/h")
                update_alarm(alarm_device, radiation_level, RADIATION_THRESHOLD)
            time.sleep(1)
    except KeyboardInterrupt:
        print("Program terminated by user.")
    finally:
        serial_connection.close()
        alarm_device.close()


if __name__ == "__main__":
    main()

