import time
import logging

# Configure logging
logging.basicConfig(filename='gps_coordinates_log.txt', level=logging.INFO,
                    format='%(asctime)s - %(message)s', datefmt='%Y-%m-%dT%H:%M:%S.%fZ')

# Serial port configuration
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1

def initialize_serial(port, baudrate, timeout):
    """Initializes the serial port."""
    try:
        ser = serial.Serial(port, baudrate, timeout=timeout)
        logging.info(f"Serial port {port} initialized successfully.")
        return ser
    except serial.SerialException as e:
        logging.error(f"Failed to initialize serial port: {e}")
        return None

def parse_gpgga_data(data):
    """Parses GPGGA sentence to extract latitude, longitude, and altitude."""
    try:
        if data.startswith('$GPGGA'):
            parts = data.split(',')
            if parts[6] == '1':  # Fix quality: 0=invalid, 1=GPS fix
                latitude = parts[2]
                longitude = parts[4]
                altitude = parts[9]
                return latitude, longitude, altitude
    except Exception as e:
        logging.error(f"Error parsing GPGGA data: {e}")
    return None, None, None

def log_coordinates(latitude, longitude, altitude):
    """Logs the coordinates to a file."""
    try:
        log_message = f"Latitude: {latitude}, Longitude: {longitude}, Altitude: {altitude} m"
        logging.info(log_message)
        print(f"Latitude: {latitude}, Longitude: {longitude}, Altitude: {altitude} m")
    except Exception as e:
        logging.error(f"Error logging coordinates: {e}")

def main():
    """Main function to read GPS data and log coordinates."""
    ser = initialize_serial(SERIAL_PORT, BAUD_RATE, TIMEOUT)
    if ser is None:
        print("Failed to initialize serial port. Exiting.")
        return

    try:
        while True:
            try:
                line = ser.readline().decode('ascii', errors='replace').strip()
                latitude, longitude, altitude = parse_gpgga_data(line)

                if latitude and longitude and altitude:
                    log_coordinates(latitude, longitude, altitude)
            except Exception as e:
                logging.error(f"Error reading or processing data: {e}")
            time.sleep(1)  # Reduced delay for responsiveness
    except KeyboardInterrupt:
        print("Program terminated by user.")
    finally:
        if ser and ser.is_open:
            ser.close()
            logging.info("Serial port closed.")

if __name__ == "__main__":
    main()

