import serial
from flask import Flask, Response, request, jsonify, abort

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Constants
DEFAULT_SERIAL_PORT = '/dev/ttyUSB0'
DEFAULT_BAUDRATE = 9600
SERIAL_TIMEOUT = 1  # seconds
INCOMING_DATA_BUFFER_SIZE = 10  # number of lines to buffer

# Global variables
app = Flask(__name__)
data_manager = None  # Initialize later to handle potential errors during app startup
serial_communicator = None  # Initialize later

# --- Data Management Class ---
class DataManager:
    """
    Manages the in-memory data store.
    """
    def __init__(self):
        self.data = [
            {'id': 1, 'name': 'Item 1', 'done': False},
            {'id': 2, 'name': 'Item 2', 'done': True}
        ]
        self.next_id = 3
        self.lock = threading.Lock()  # Ensure thread-safe access

    def get_all(self):
        """Returns all data."""
        with self.lock:
            return self.data.copy()  # Return a copy to prevent direct modification

    def get_by_id(self, item_id):
        """Returns data by ID."""
        with self.lock:
            return next((item for item in self.data if item['id'] == item_id), None)

    def create(self, name, done):
        """Creates new data."""
        with self.lock:
            if not name:
                return None  # Or raise an exception

            item = {
                'id': self.next_id,
                'name': name,
                'done': bool(done)  # Ensure boolean type
            }
            self.data.append(item)
            self.next_id += 1
            return item

# --- Serial Communication Class ---
class SerialCommunicator:
    """
    Manages serial communication with the instrument.
    """
    def __init__(self, port, baudrate):
        self.port = port
        self.baudrate = baudrate
        self.ser = None
        self.lock = threading.Lock()
        self.running = False

    def open(self):
        """Opens the serial port."""
        with self.lock:
            try:
                if self.ser and self.ser.is_open:
                    return  # Already open

                self.ser = serial.Serial(self.port, self.baudrate, timeout=SERIAL_TIMEOUT)
                logging.info(f"Serial port {self.port} opened successfully.")
                self.running = True
            except serial.SerialException as e:
                logging.error(f"Error opening serial port {self.port}: {e}")
                self.ser = None
                self.running = False
                raise

    def close(self):
        """Closes the serial port."""
        with self.lock:
            if self.ser and self.ser.is_open:
                self.ser.close()
                logging.info(f"Serial port {self.port} closed.")
                self.ser = None
                self.running = False

    def send(self, command):
        """Sends a command to the instrument."""
        with self.lock:
            if not self.ser or not self.ser.is_open:
                raise Exception(f"Serial port not open. Cannot send command: {command}")

            try:
                self.ser.write(f"{command}\n".encode('utf-8'))
                bytes_sent = self.ser.write(f"{command}\n".encode('utf-8'))
                if bytes_sent == 0:
                    raise Exception("No bytes sent. Serial port might be closed.")
                logging.debug(f"Sent command: {command}")
                return bytes_sent
            except serial.SerialException as e:
                logging.error(f"Error sending command: {e}")
                raise

    def receive_line(self):
        """Receives a line from the instrument."""
        with self.lock:
            if not self.ser or not self.ser.is_open:
                raise Exception("Serial port not open. Cannot receive data.")

            try:
                line = self.ser.readline().decode('utf-8', errors='ignore').strip()
                if line:
                    logging.debug(f"Received line: {line}")
                    return line
                else:
                    return None
            except serial.SerialException as e:
                logging.error(f"Error receiving data: {e}")
                raise

    def __enter__(self):
        self.open()
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        self.close()

# --- Flask Routes ---
@app.route('/version', methods=['GET'])
def get_version():
    """Gets the instrument version."""
    try:
        with serial_communicator:
            serial_communicator.send('*IDN?')
            response = serial_communicator.receive_line()
            if response:
                return Response(response + '\n', mimetype='text/plain')
            else:
                return Response("No response received.\n", mimetype='text/plain', status=504)
    except Exception as e:
        logging.error(f"Error getting version: {e}")
        return Response(str(e) + '\n', mimetype='text/plain', status=500)

@app.route('/data', methods=['GET'])
def get_data():
    """Gets all data."""
    return jsonify(data_manager.get_all())

@app.route('/data/<int:item_id>', methods=['GET'])
def get_data_by_id(item_id):
    """Gets data by ID."""
    item = data_manager.get_by_id(item_id)
    if item:
        return jsonify(item)
    else:
        abort(404)

@app.route('/data', methods=['POST'])
def create_data():
    """Creates new data."""
    try:
        name = request.json['name']
        done = request.json.get('done', False)  # Default to False if not provided
        item = data_manager.create(name, done)
        if item:
            return jsonify(item), 201
        else:
            abort(400)  # Bad Request for invalid input
    except KeyError:
        abort(400, description="Name is required")
    except Exception as e:
        logging.error(f"Error creating data: {e}")
        abort(500)

# --- Shutdown Handling ---
def shutdown_server():
    """Shuts down the Flask app."""
    func = request.environ.get('werkzeug.server.shutdown')
    if func is None:
        raise RuntimeError('Not running with the Werkzeug Server')
    func()

@app.route('/shutdown', methods=['POST'])
def shutdown():
    """Shutdown the server."""
    shutdown_server()
    return 'Server shutting down...'

# --- Main ---
if __name__ == '__main__':
    serial_port = os.environ.get('SERIAL_PORT', DEFAULT_SERIAL_PORT)
    baudrate = int(os.environ.get('BAUDRATE', DEFAULT_BAUDRATE))

    try:
        data_manager = DataManager()
        serial_communicator = SerialCommunicator(serial_port, baudrate)
        serial_communicator.open()  # Initialize serial connection
        app.run(host='0.0.0.0', port=5000, debug=False, use_reloader=False) # Disable reloader for production
    except Exception as e:
        logging.critical(f"Application startup failed: {e}")
    finally:
        if serial_communicator:
            serial_communicator.close()

