                    format="%(asctime)s - Power: %(message)s W")

# Serial port configuration for the energy meter
SERIAL_PORT = "/dev/serial0"
BAUD_RATE = 9600
TIMEOUT = 1


@contextlib.contextmanager
def open_serial(port, baudrate, timeout):
    """Context manager to handle serial port opening and closing."""
    try:
        serial_connection = serial.Serial(port, baudrate, timeout=timeout)
        yield serial_connection
    finally:
        if serial_connection and serial_connection.is_open:
            serial_connection.close()


def read_meter_data(serial_connection):
    """Read a line from the serial port and return the decoded string."""
    try:
        line = serial_connection.readline().decode("ascii", errors="replace").strip()
